<template>
  <sdPageHeader title="Add New">
    <sdButton class="btn-add_new" size="default" key="1" type="primary">
      <router-link to="/crud/fireStore-view">View All</router-link>
    </sdButton>
  </sdPageHeader>
  <Main>
      <a-row :gutter="15">
        <a-col :xs="24">
          <RecordFormWrapper>
            <sdCards headless>
              <a-row justify="center">
                <a-col :xl="10" :md="16" :xs="24">
                  <BasicFormWrapper>
                    <a-form
                      class="add-record-form"
                      :style="{ width: '100%' }"
                      layout="vertical"
                      name="addnew"
                      :model="formState"
                      @finish="handleSubmit"
                    >
                      <!-- <figure class="pro-image align-center-v">
                        <img
                          :src="
                            url === null
                              ? require('@/static/img/avatar/profileImage.png')
                              : `https://demo.jsnorm.com/laravel/strikingdash-api/${url}`
                          "
                          alt=""
                        />
                        <figcaption>
                          <a-upload v-bind="props">
                            <a class="upload-btn" to="#">
                              <sdFeatherIcons type="camera" size="16" />
                            </a>
                          </a-upload>
                          <div class="info">
                            <sdHeading as="h4">Profile Photo</sdHeading>
                          </div>
  
                          <div v-if="isFileLoading" class="isUploadSpain">
                            <a-spin />
                          </div>
                        </figcaption>
                      </figure> -->
                      <a-form-item name="event_name" label="Event Name">
                        <a-input v-model:value="formState.name" placeholder="Input Event Name" />
                      </a-form-item>
                      <a-form-item name="event_code" label="Event Code">
                        <a-input v-model:value="formState.code" placeholder="Input Event Code" />
                      </a-form-item>
                      <a-form-item label="Event Start Date">
                        <a-date-picker :style="{ width: '100%' }" v-model:value="join" :format="dateFormat" />
                      </a-form-item>
                      <a-form-item label="Event End Date">
                        <a-date-picker :style="{ width: '100%' }" v-model:value="join" :format="dateFormat" />
                      </a-form-item>
                      <div class="record-form-actions text-right">
                        <sdButton size="default" htmlType="Save" type="success">
                          {{ isLoading ? 'Loading...' : 'Submit' }}
                        </sdButton>
                      </div>
                    </a-form>
                  </BasicFormWrapper>
                </a-col>
              </a-row>
            </sdCards>
          </RecordFormWrapper>
        </a-col>
      </a-row>
    </Main>
</template>
<script>
import { RecordFormWrapper } from './style';
import { Main, BasicFormWrapper } from '../../styled';
import { useStore } from 'vuex';
import { computed, reactive, ref } from 'vue';
import moment from 'moment';

const dateFormat = 'YYYY/MM/DD';

const AddNew = {
  name: 'AddNew',
  components: { RecordFormWrapper, Main, BasicFormWrapper },
  setup() {
    const { state, dispatch } = useStore();

    const isLoading = computed(() => state.fireStore.loading);
    const url = computed(() => state.fireStore.url);
    const isFileLoading = computed(() => state.fireStore.fileLoading);
    const join = ref('');

    const handleSubmit = values => {
      dispatch('fireStoreCrudSubmitData', {
        ...values,
        image: url.value,
        join: moment(join.value).format('YYYY/MM/DD'),
        id: new Date().getTime(),
      });
      dispatch('fireStoreFileClear');
    };

    const props = {
      name: 'file',
      action: 'https://www.mocky.io/v2/5cc8019d300000980a055e76',
      multiple: false,
      showUploadList: false,
      headers: {
        authorization: 'authorization-text',
      },
      onChange(info) {
        if (info.file.status !== 'uploading') {
          dispatch('fireStoreFileUploader', info.file.originFileObj);
        }
      },
    };

    const formState = reactive({
      name: '',
      email: '',
      country: '',
      city: '',
      company: '',
      position: '',
      status: '',
    });

    return {
      isLoading,
      url,
      isFileLoading,
      handleSubmit,
      props,
      dateFormat,
      formState,
      join,
    };
  },
};

export default AddNew;
</script>
